      <header class="topbar"><div class="brand"><span class="checker"></span> AB<span class="brand-separator"> / </span><small>CORRIDA SEM REGRAS</small></div>
        <div class="top-actions"><div class="wallet"><span>CRÉDITOS</span><b id="wallet"></b></div><button class="nav-btn" id="garage-btn">${G.garage} GARAGEM</button><button class="icon-btn" data-action="help" aria-label="Como jogar">${G.help}</button><button class="icon-btn" data-action="mute" aria-label="Silenciar áudio">${G.sound}</button></div>
      </header>
